#!/usr/bin/env python3
"""Build the complete merchandise/subscription catalog and compatible /shop route."""
import json
from checkout import any_ready
from site_metadata import write_html
from html import escape as e
from site_components import ROOT,CATALOG,merchandise,mobile_toolbar
from site_images import image_tag,brand_mark

def catalog_page():
    report=json.loads((ROOT/'data/numerology-topics.json').read_text())['report']
    plans=json.loads((ROOT/'data/subscriptions.json').read_text())['plans']
    subscriptions=[]
    for plan in plans:
        art=''.join(image_tag(key,'../','Sun, Moon, or rising emblem' if plan['id']=='astrology' else 'Crystal Eye tarot artwork') for key in plan['images'])
        subscriptions.append(f'''<article class="subscription-offer" id="{plan['id']}-subscription" data-offering="{plan['id']}-subscription"><div class="subscription-art catalog-{plan['id']}-art" aria-hidden="true">{art}</div><p class="catalog-eyebrow">{plan['id'].title()} / Daily ritual</p><h3>{e(plan['name'])}</h3><p>{e(plan['description'])}</p><p class="catalog-price">${plan['price']} <span>CAD / month</span></p><ul>{''.join('<li>'+e(benefit)+'</li>' for benefit in plan['benefits'])}</ul><p class="catalog-status">Coming soon · enrollment is not open</p><div class="catalog-actions"><a class="button button-gold" href="../{plan['preview']}">Try the free preview →</a><a class="text-link" href="../{plan['details']}">Subscription details →</a></div></article>''')
    checkout_open=any_ready()
    catalog_status='Stripe checkout available for ready merchandise · subscriptions coming soon' if checkout_open else 'checkout and subscriptions are coming soon'
    ordering_status='Physical merchandise ships within Canada for a flat $9.99 CAD. Applicable tax is added at Stripe checkout. Subscriptions and the numerology report are not yet available to purchase.' if checkout_open else 'Products and services are listed here at their announced Canadian-dollar prices. Checkout is not connected yet: no orders, payments, or subscription enrollments are being accepted.'
    fulfillment_note='Review the product format, delivery, shipping charges where applicable, and purchase terms in checkout before paying. Product images show supplied artwork, not finalized packaging.' if checkout_open else 'Product formats, fulfillment, shipping where applicable, and final purchase terms will be available before ordering opens. Product images show supplied artwork, not finalized packaging.'
    body=f'''<section class="wrap catalog-hero"><p class="catalog-eyebrow">Merchandise &amp; subscriptions</p><h1>A little wonder.<br><em>A ritual of your own.</em></h1><p>All our merchandise, readings, and daily subscriptions in one place. Explore what fits your practice, try the free previews, and get to know what is coming next.</p><nav class="catalog-jumps" aria-label="Catalog sections"><a href="#products">Books &amp; decks</a><a href="#numerology-report">Numerology report</a><a href="#subscriptions">Daily subscriptions</a><a href="#psychic-reading">Psychic Readings</a></nav><p class="catalog-status">All prices in CAD · {catalog_status}</p></section><div id="products">{merchandise('../',shop_page=True)}</div><section class="wrap catalog-section" id="numerology-report"><div class="catalog-heading"><p class="catalog-eyebrow">A one-time reading</p><h2>Your numbers,<br><em>in context.</em></h2></div><article class="report-offer" data-offering="numerology-report">{image_tag('numerology.topic.life-path','../','Life Path illustration from the numerology collection')}<div><h3>{e(report['name'])}</h3><p>A planned expanded reading bringing together all 21 chart positions, from Personality, Life Path, and Destiny to your cycles, Pinnacles, and Challenges.</p><p class="catalog-price">${report['price']} <span>CAD · one-time purchase</span></p><p class="catalog-status">Coming soon · remaining guide content is in preparation</p><a class="button button-outline" href="../numerology/report.html">Explore the full report →</a><p class="catalog-note">Want to begin now? <a href="../numerology/index.html#calculator">Find your first three numbers for free.</a></p></div></article></section><section class="wrap catalog-section" id="subscriptions"><div class="catalog-heading"><p class="catalog-eyebrow">Daily perspectives</p><h2>One small ritual.<br><em>Something to return to.</em></h2><p>Choose astrology, tarot, or explore both previews. These are separate monthly subscriptions; buying merchandise does not enroll you in either one.</p></div><div class="subscription-grid">{''.join(subscriptions)}</div></section><section class="wrap catalog-section catalog-ordering" id="ordering"><p class="catalog-eyebrow">{'Ordering information' if checkout_open else 'Before ordering opens'}</p><h2>Have a look.<br><em>Take your time.</em></h2><p>{ordering_status}</p><p>{fulfillment_note} The numerology report will be offered once its remaining content and delivery details are ready.</p><div class="free-practice"><h3>Keep exploring for free.</h3><a href="../astrology/index.html#signs">Daily horoscope one-liners →</a><a href="../tarot/index.html#daily-draw">A daily tarot card →</a><a href="../numerology/index.html#calculator">Your first three numbers →</a></div></section>'''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b19"><meta name="description" content="All Crystaleye products and subscriptions: tarot guide, deck, bundle, full numerology report, daily astrology email, and daily three-card tarot. Prices in CAD."><title>Merchandise &amp; Subscriptions | Crystaleye</title><link rel="canonical" href="../merchandise/index.html"><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/merchandise.css"><link rel="stylesheet" href="../assets/catalog.css"><link rel="stylesheet" href="../assets/cyberpunk.css"><link rel="stylesheet" href="../assets/mobile-toolbar.css?v=3"><script src="../assets/site.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="../index.html" aria-label="Crystaleye home">{brand_mark('../')}<span>crystaleye<span class="brand-dot">.</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 6h14M3 14h14"/></svg></button><nav id="site-nav" aria-label="Main navigation"><a href="../astrology/index.html">Astrology</a><a href="../tarot/index.html">Tarot</a><a href="../numerology/index.html">Numerology</a></nav><a class="header-cta" href="#products">Explore the collection →</a></header><main id="main">{body}</main><footer class="site-footer wrap catalog-footer"><a class="brand" href="../index.html">crystaleye<span class="brand-dot">.</span></a><nav aria-label="Footer"><a href="#products">Books &amp; decks</a><a href="#numerology-report">Numerology report</a><a href="#subscriptions">Daily subscriptions</a><a href="../index.html">Crystaleye home →</a></nav><p>Numerology, astrology, and tarot offer symbolic prompts for reflection and entertainment, not guaranteed predictions.</p></footer>{mobile_toolbar('../','Shop')}</body></html>'''

def main():
    html=catalog_page()
    for folder in ['merchandise','shop']:
        dest=ROOT/folder;dest.mkdir(exist_ok=True);write_html(dest/'index.html',html)
    print('Built all-six-offers merchandise page and compatible shop page.')
if __name__=='__main__':main()
